static int mtk_jpegenc_hw_init_irq ( struct mtk_jpegenc_comp_dev * dev ) { struct platform_device * pdev = dev -> plat_dev ; int ret ; dev -> jpegenc_irq = platform_get_irq ( pdev , 0 ) ; ret = devm_request_irq ( & pdev -> dev , dev -> jpegenc_irq , mtk_jpegenc_hw_irq_handler , 0 , pdev -> name , dev ) ; if ( ret ) { dev_err ( & pdev -> dev , "Failed to devm_request_irq %d (%d)" , dev -> jpegenc_irq , ret ) ; return ret ; } return 0 ; } 